//! Authored/uncompiled/unrun. No native FFV1, producer, guard or media acceptance.
use super::*;
use serde_json::{Value,json};
use crate::video_candidate::{parse_request,prepare_candidate,request_fingerprint};
fn production(v2:bool)->crate::video_production::VideoProductionRequest {serde_json::from_str(if v2{include_str!("../../examples/video-production-request-v2.json")}else{include_str!("../../examples/video-production-request-v1.json")}).unwrap()}
fn probe(width:u32,height:u32,count:usize)->Vec<u8>{let mut v:Value=serde_json::from_str(include_str!("../../tests/fixtures/video/probe-ffv1-v1.json")).unwrap();for key in ["width","coded_width"]{v["streams"][0][key]=json!(width);}for key in ["height","coded_height"]{v["streams"][0][key]=json!(height);}v["streams"][0]["nb_read_frames"]=json!(count.to_string());let base=v["frames"][0].clone();v["frames"]=json!((0..count).map(|n|{let mut f=base.clone();f["width"]=json!(width);f["height"]=json!(height);f["pts"]=json!(n*40);f["best_effort_timestamp"]=json!(n*40);f}).collect::<Vec<_>>());serde_json::to_vec(&v).unwrap()}
fn element(id:u64,data:&[u8])->Vec<u8>{let encoded=id.to_be_bytes();let start=encoded.iter().position(|v|*v!=0).unwrap();let mut out=encoded[start..].to_vec();let size=data.len() as u64;let width=(1..=8).find(|w|size<(1_u64<<(7*w))-1).unwrap();let value=size|(1_u64<<(7*width));out.extend_from_slice(&value.to_be_bytes()[8-width..]);out.extend_from_slice(data);out}
fn uint(id:u64,n:u64)->Vec<u8>{let b=n.to_be_bytes();let start=b.iter().position(|v|*v!=0).unwrap_or(7);element(id,&b[start..])}
fn container(width:u32,height:u32,count:usize,payload:u8)->Vec<u8>{let colors=element(0x55b0,&[uint(0x55b1,1),uint(0x55b9,1),uint(0x55ba,1),uint(0x55bb,1)].concat());let video=element(0xe0,&[uint(0xb0,u64::from(width)),uint(0xba,u64::from(height)),colors].concat());let mut private=vec![0;40];private[16..20].copy_from_slice(b"FFV1");let track=element(0xae,&[uint(0xd7,1),uint(0x73c5,7),uint(0x83,1),uint(0x23e383,40_000_000),uint(0x88,0),uint(0x9c,0),element(0x22b59c,b"und"),element(0x86,b"V_MS/VFW/FOURCC"),element(0x63a2,&private),video].concat());let mut segment=[element(0x1549a966,&uint(0x2ad7b1,1_000_000)),element(0x1654ae6b,&track)].concat();for n in 0..count{segment.extend(element(0x1f43b675,&[uint(0xe7,n as u64*40),element(0xa3,&[0x81,0,0,0x80,payload])].concat()));}[element(0x1a45dfa3,&element(0x4282,b"matroska")),element(0x18538067,&segment)].concat()}
fn candidate()->Value{let mut v:Value=serde_json::from_str(include_str!("../../examples/video-candidate-request-v1.json")).unwrap();v["schema"]=json!(crate::video_candidate::SCHEMA_V2);v["profile"]=json!(crate::video_candidate::PROFILE_V2);v["source"]["media"]["width"]=json!(1280);v["source"]["media"]["height"]=json!(720);v["source"]["media"]["frame_count"]=json!(251);v["source"]["media"]["duration_ticks"]=json!(10040);v["source"]["logical_bytes"]=json!(33554432);v["limits"]=serde_json::to_value(production(true).limits).unwrap();v}
#[test] fn v2_admission_is_explicit_and_v1_does_not_inherit_larger_limits(){let v2=production(true);let payload=crate::video_production::admission(&v2).unwrap();assert!(payload>1_073_741_824);let mut old=v2.clone();old.schema="optiflow.video-production-request.v1".into();assert!(crate::video_production::admission(&old).is_err());assert!(crate::video_production::admission(&production(false)).is_ok());}
#[test] fn provider_quota_capture_copies_and_publication_reserve_are_all_admitted(){let mut r=production(true);r.limits.memory_bytes=536_870_912;assert!(crate::video_production::admission(&r).is_err());r=production(true);r.limits.temporary_bytes=134_217_728;assert!(crate::video_production::admission(&r).is_err());r=production(true);r.limits.elapsed_ms=30_001;assert!(crate::video_production::admission(&r).is_err());}
#[test] fn candidate_schema_profile_and_fingerprint_have_explicit_version_identity(){let v=candidate();let r=parse_request(&v).unwrap();prepare_candidate(&r).unwrap();let mut old=v.clone();old["schema"]=json!(crate::video_candidate::SCHEMA);old["profile"]=json!(crate::video_candidate::PROFILE);assert!(parse_request(&old).is_err());let old:crate::video_candidate::VideoCandidateRequest=serde_json::from_str(include_str!("../../examples/video-candidate-request-v1.json")).unwrap();let mut same=old.clone();same.schema=crate::video_candidate::SCHEMA_V2.into();same.profile=crate::video_candidate::PROFILE_V2.into();assert_ne!(request_fingerprint(&old),request_fingerprint(&same));}
#[test] fn v2_never_admits_lossy_or_unknown_profile_options(){let mut v=candidate();v["operation"]=json!({"kind":"h264_lossy","crf":20,"preset":"slow"});assert!(parse_request(&v).is_err());v=candidate();v["profile"]=json!(crate::video_candidate::PROFILE);assert!(parse_request(&v).is_err());v=candidate();v["adopt_or_replace_source"]=json!(true);assert!(parse_request(&v).is_err());}
#[test] fn explicit_probe_v2_accepts_broader_geometry_but_legacy_parser_refuses(){let bytes=probe(1280,720,2);assert!(crate::video_probe::parse_ffv1_observation(&bytes).is_err());let observed=crate::video_probe::parse_ffv1_observation_v2(&bytes).unwrap();assert_eq!(observed.media.width,1280);assert!(!observed.media.feature_observation_complete);}
#[test] fn probe_frame_and_decoded_limits_intersect_without_truncation(){assert!(crate::video_probe::parse_ffv1_observation_v2(&probe(2,2,3000)).is_ok());assert!(crate::video_probe::parse_ffv1_observation_v2(&probe(2,2,3001)).is_err());assert!(crate::video_probe::parse_ffv1_observation_v2(&probe(1280,720,388)).is_ok());assert!(crate::video_probe::parse_ffv1_observation_v2(&probe(1280,720,389)).is_err());}
#[test] fn independent_container_v2_preserves_every_bounded_global_packet(){let bytes=container(1280,720,251,7);assert!(crate::video_container::inspect(&bytes).is_err());let a=crate::video_container::inspect_v2(&bytes).unwrap();assert_eq!(a.profile,Profile::BoundedV2.container_profile());assert_eq!(a.packets.len(),251);assert_eq!(a.packets[250].pts_milliseconds,10000);assert!(crate::video_container::inspect_v2(&container(2,2,3001,7)).is_err());}
#[test] fn payload_clock_or_cross_profile_changes_cannot_be_stream_copy_equivalence(){let a=crate::video_container::inspect_v2(&container(2,2,2,7)).unwrap();let b=crate::video_container::inspect_v2(&container(2,2,2,8)).unwrap();assert!(crate::video_container::compare_stream_copy(&a,&b).is_err());let mut changed=a.clone();changed.packets[1].pts_milliseconds=81;assert!(crate::video_container::compare_stream_copy(&a,&changed).is_err());let old=crate::video_container::inspect(&container(2,2,2,7)).unwrap();assert!(crate::video_container::compare_stream_copy(&a,&old).is_err());}
#[test] fn markers_cannot_relabel_large_v2_members_as_v1_or_claim_replacement(){let digest=json!({"algorithm":"blake3-256","value":"a".repeat(64)});let mut m=json!({"schema":"optiflow.video-candidate-artifact-set.v2","set_id":"018f47a2-4f17-7b00-8000-000000000002","created_at":"2026-11-10T00:00:00Z","state":"committed","members":[{"kind":"candidate_video","file_name":"candidate.mkv","size_bytes":33554432,"digest":digest},{"kind":"evidence","file_name":"evidence.json","size_bytes":1048576,"digest":digest}]});assert!(crate::contracts::validate(crate::contracts::Contract::VideoCandidateArtifactSetV2,&m).is_ok());assert!(crate::contracts::validate(crate::contracts::Contract::VideoCandidateArtifactSet,&m).is_err());m["replacement_authority"]=json!(true);assert!(crate::contracts::validate(crate::contracts::Contract::VideoCandidateArtifactSetV2,&m).is_err());}
